/**
 * Searches the ingested Celestial dataset for deep spiritual or numerological guidance
 */
export function findSpiritualGuidance(userQuery: string): string | null {
  const q = userQuery.toLowerCase();
  
  // 1. Check for numerology or lucky number queries
  if (q.includes('number') || q.includes('numerology') || q.includes('lucky') || q.includes('ank') || q.includes('chaldean')) {
    const match = NUMEROLOGY_DATASET.find(item => {
      const itemWords = item.query.toLowerCase().split(' ').filter(w => w.length > 3);
      return itemWords.some(w => q.includes(w));
    });
    if (match) return match.response;
  }

  // 2. Check for deity or spiritual dilemma queries (Krishna, Ganesha, Shiva, Gita, Peace)
  if (q.includes('krishna') || q.includes('ganesh') || q.includes('shiva') || q.includes('god') || q.includes('bhagwan') || q.includes('dharma')) {
    const match = DEITY_GUIDANCE_DATASET.find(item => {
      const itemWords = item.query.toLowerCase().split(' ').filter(w => w.length > 4);
      return itemWords.some(w => q.includes(w));
    });
    if (match) return match.response;
  }

  // 3. Check for emotional confusion, career anxiety, or seeking peace
  if (q.includes('peace') || q.includes('fear') || q.includes('confus') || q.includes('scared') || q.includes('darr') || q.includes('shanti')) {
    const match = SPIRITUAL_COUNSEL_DATASET.find(item => {
      const itemWords = item.query.toLowerCase().split(' ').filter(w => w.length > 4);
      return itemWords.some(w => q.includes(w));
    });
    if (match) return match.response;
  }

  return null;
}
